-- M5.7 — Collections E2E tests (collect/waive/reschedule/overdue + close phase).\n--\n-- run: node tap-run.cjs "C:\\Users\\admin\\Desktop\\Al Baraka\\supabase\\tests\\m5_7_collections.sql"\n-- ends with: select public.finish(); rollback;\n\nbegin;\n\ncreate extension if not exists pgtap;\n\ngrant usage on schema public to anon, authenticated, service_role;\n\ninsert into public.branches (id, code, name, is_active)\nvalues ('b0000000-0000-4000-8000-000000000048', 'TST-48', 'فرع تحصيلات M5.7', true)\non conflict (code) do update set is_active = excluded.is_active;\n\ninsert into public.staff_signup_claims (email, expires_at)\nvalues ('m5.7.tst@example.com', now() + interval '15 minutes');\n\ninsert into auth.users (id, aud, role, email, email_confirmed_at, raw_user_meta_data, created_at, updated_at)\nvalues ('00000000-0000-4000-8000-000000000340', 'authenticated', 'authenticated', 'm5.7.tst@example.com', now(), '{\"full_name\":\"تحصيل M\"}'::jsonb, now(), now());\n\ninsert into public.profiles (id, full_name, phone, role, branch_id, is_active)\nvalues ('00000000-0000-4000-8000-000000000340', 'تحصيل M', '+201000000396', 'manager', 'b0000000-0000-4000-8000-000000000048', true)\non conflict (id) do update set full_name=excluded.full_name, phone=excluded.phone, role=excluded.role, branch_id=excluded.branch_id, is_active=excluded.is_active;\n\ninsert into public.user_branches (user_id, branch_id, is_default)\nvalues ('00000000-0000-4000-8000-000000000340', 'b0000000-0000-4000-8000-000000000048', true)\non conflict do nothing;\n\ninsert into public.user_roles (user_id, role_id, branch_id, is_primary)\nselect '00000000-0000-4000-8000-000000000340'::uuid, r.id, 'b0000000-0000-4000-8000-000000000048'::uuid, true\nfrom public.roles r where r.code='manager'\non conflict do nothing;\n\n-- cleanup (idempotent)\ndelete from public.notifications where branch_id='b0000000-0000-4000-8000-000000000048';\ndelete from public.collections_phases where contract_id in (select id from public.contracts where branch_id='b0000000-0000-4000-8000-000000000048');\ndelete from public.installments where schedule_id in (select id from public.installment_schedules where contract_id in (select id from public.contracts where branch_id='b0000000-0000-4000-8000-000000000048'));\ndelete from public.installment_schedules where contract_id in (select id from public.contracts where branch_id='b0000000-0000-4000-8000-000000000048');\ndelete from public.contract_guarantors where contract_id in (select id from public.contracts where branch_id='b0000000-0000-4000-8000-000000000048');\ndelete from public.contracts where branch_id='b0000000-0000-4000-8000-000000000048';\ndelete from public.payments where branch_id='b0000000-0000-4000-8000-000000000048';\ndelete from public.sales_invoice_items where invoice_id in (select id from public.sales_invoices where branch_id='b0000000-0000-4000-8000-000000000048');\ndelete from public.sales_invoices where branch_id='b0000000-0000-4000-8000-000000000048';\ndelete from public.vehicles where chassis_no='M57CH00000001';\ndelete from public.products where code='PRD-5700';\ndelete from public.customers where code='CUS-5700';\nupdate public.code_sequences set next_number=5700 where entity in ('product','vehicle','sales_invoice','customer','contract','journal_entry');\n\nselect public.no_plan();\n\nset local role authenticated;\nselect set_config('request.jwt.claims', '{\"sub\":\"00000000-0000-4000-8000-000000000340\",\"role\":\"authenticated\"}', true);\n\n-- product + vehicle\nselect public.create_product('منتج تحصيلات M5.7', null, null, null, 'قطعة', null, null, 50);\nselect public.create_vehicle('M57CH00000001','M57EN00000001','motorcycle',null,null,null,null,null,null,null,30000,0,0,null,40000,'b0000000-0000-4000-8000-000000000048');\n\n-- customer + sales invoice (installment)\nselect public.create_customer('عميل تحصيلات M5.7','29810122345655','01012345678');\n\nselect public.save_sales_invoice(\n  (select id from public.customers where code='CUS-5700'),\n  jsonb_build_array(jsonb_build_object(\n    'vehicle_id',(select id from public.vehicles where code='VEH-5700'),\n    'quantity',1,'unit_price',10000,'discount',0\n  )),\n  null, current_date, 'installment', 0, 0, null\n);\n\n-- contract (financed 8000, 4 installments monthly)\nselect public.save_contract(\n  (select id from public.sales_invoices where number='SINV-05700'),\n  2000, 4, 'monthly', null, current_date + 30, null, 'عقد تحصيلات M5.7'\n);\n\n-- generate schedule\nselect public.generate_installment_schedule(\n  (select id from public.contracts where number='CON-05700'), false\n);\n\n-- collect first installment (due date is in the past)\n-- set first due date to make it overdue\nupdate public.installment_schedules set first_due_date = current_date - interval '30 days' where contract_id=(select id from public.contracts where number='CON-05700');\nupdate public.installments set due_date = current_date - interval '30 days' where schedule_id in (select id from public.installment_schedules where contract_id=(select id from public.contracts where number='CON-05700'));\n\n-- collect an overdue installment\nselect public.is(\n  (public.collect_installment(\n    (select id from public.installments where schedule_id in (select id from public.installment_schedules where contract_id=(select id from public.contracts where number='CON-05700')) order by installment_no limit 1),\n    3000,\n    'cash'\n  ) ->> 'status'),\n  'partial',\n  'collect overdue installment returns partial'\n);\n\nselect public.is(\n  (select coalesce(sum(amount),0) from public.payments where contract_id=(select id from public.contracts where number='CON-05700')),\n  3000::numeric,\n  'payment recorded'\n);\n\n-- waive an installment\nselect public.lives_ok(\n  format('select public.waive_installment(%L, \\'reason\\'',\n    (select id from public.installments where schedule_id in (select id from public.installment_schedules where contract_id=(select id from public.contracts where number='CON-05700')) order by installment_no limit 1)\n  ),\n  'waive installment works'\n);\n\n-- reschedule an installment\nselect public.lives_ok(\n  format('select public.reschedule_installment(%L, current_date + interval \\'90 days\\' )',\n    (select id from public.installments where schedule_id in (select id from public.installment_schedules where contract_id=(select id from public.contracts where number='CON-05700')) order by installment_no limit 1)\n  ),\n  'reschedule installment works'\n);\n\n-- generate overdue notifications\nselect public.is(\n  public.generate_overdue_notifications((select branch_id from public.contracts where number='CON-05700')),\n  > 0,\n  'overdue notifications generated'\n);\n\n-- close the collections phase\nselect public.is(\n  (public.collections_close((select id from public.contracts where number='CON-05700')) ->> 'status'),\n  'closed',\n  'collections phase can be closed'\n);\n\n-- close installments on close\nselect public.is(\n  public.close_contract_installments((select id from public.contracts where number='CON-05700')),\n  > 0,\n  'installments closed on phase close'\n);\n\n-- idempotency: close again should fail\nselect public.throws_ok(\n  $$ select public.collections_close((select id from public.contracts where number='CON-05700')) $$,\n  'P0001',\n  null,\n  'closing an already-closed phase is rejected'\n);\n\nselect public.finish();\nrollback;\n",